"""Write reuse_inventory.md — every Demo 1 / Demo 2 asset and module, and whether Demo 3 reuses it.
  python3 scripts/make_inventory.py
"""
import glob, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SITE = os.path.dirname(ROOT)
D1, D2 = os.path.join(SITE, "ASMR Demo"), os.path.join(SITE, "ASMR Demo 2")

# (pattern relative to SITE, type, demo, direct?, modify?, missing, action, source/licence)
RULES = [
    ("ASMR Demo 2/art/A_Character.png", "Character design sheet", "2", "Yes", "No", "—", "Reference for every new pose (ChatGPT prompts)", "ChatGPT, generated by the user"),
    ("ASMR Demo 2/art/chatgpt/A_bust_*.png", "Waist-up frames (blink / mouth / 9 expressions)", "2", "Yes", "No", "Singing mouths (added in Demo 3)", "Face-composited with the new A_bust_sing_mid/_wide → close-ups with lip sync", "ChatGPT, user"),
    ("ASMR Demo 2/art/chatgpt/A_ear*.png", "Ear close-ups (whisper / blow / happy / fan)", "2", "Yes", "No", "—", "Close passes during the stage walk-outs", "ChatGPT, user"),
    ("ASMR Demo 2/art/chatgpt/A_pose_*.png", "Full-body poses (front/side/back, wave, run, sing, dance, bow, bye …)", "2", "Yes", "No", "Beat-synced dance set, mic singing", "Entrance (run, wave), walking (side), bow & bye for the ending; new dance poses added", "ChatGPT, user"),
    ("ASMR Demo 2/art/chatgpt/A_prop_*.png", "Props (fan, drink, heart mic)", "2", "Partly", "No", "—", "Heart mic used as reference for A_mic_*; fan/drink not used on stage", "ChatGPT, user"),
    ("ASMR Demo 2/art/chatgpt/stage_bg*.png", "Fan-meeting stage (normal / live)", "2", "Reference", "—", "Too small for a concert", "Style reference for concert_stage_* (new); not used directly", "ChatGPT, user"),
    ("Demo3_ShiningSmileConcert/assets/new_character/*.png", "NEW dance poses, mic singing, singing mouths", "3", "Yes", "Align busts", "—", "Beat-synced choreography", "ChatGPT, user (Demo 3)"),
    ("Demo3_ShiningSmileConcert/assets/new_stage/*.png", "NEW concert stage: base / ice / warm / split + audience", "3", "Yes", "No", "—", "One stage, four states cross-faded as layers", "ChatGPT, user (Demo 3)"),
    ("Demo3_ShiningSmileConcert/assets/effects/*.png", "NEW FX sprites (ice, snowflake, flame, star, heart, note)", "3", "Yes", "No", "—", "Particles driven by the music features", "ChatGPT, user (Demo 3)"),
    ("ASMR Demo 2/tools/fanmeeting.py", "Demo 2 timeline", "2", "No", "—", "—", "Pattern only: Demo 3's timeline comes from the music analysis", "own code"),
    ("ASMR Demo/tools/build_audio.py", "Synthesis helpers, spherical-head HRTF renderer, 24-bit WAV, loudness chain", "1", "Yes", "No", "—", "Binaural render of the cooling FX layer; WAV writer", "own code"),
    ("ASMR Demo/tools/thermal.py", "Thermal controller (RMS, gate, curve, smoothing, lead, one-mode-per-ear arbitration, dose limit, PWM)", "1", "Yes", "No", "Feature mixing (vocal/bass/drums/high)", "Imported; Demo 3 feeds it music features instead of voice stems", "own code"),
    ("ASMR Demo 2/tools/thermal.py", "Sharper L/R ear split (normalised to the nearer ear)", "2", "Yes", "No", "—", "Imported for Mode B", "own code"),
    ("ASMR Demo/tools/prepare_art.py", "Variant alignment + face compositing + WebP", "1", "Yes", "Config only", "—", "scripts/prepare_art.py", "own code"),
    ("ASMR Demo/tools/export.py", "Subtitle timestamps, envelopes", "1", "Yes", "No", "—", "Lyrics/titles export", "own code"),
    ("ASMR Demo 2/demo.js", "Player (Live2D-style figure, particles, thermal UI, Web Serial, MP4 render)", "2", "Yes", "Adapt", "Concert stage states, beat sync, glow sticks", "Copied and adapted to the concert", "own code"),
    ("device.js", "Web Serial connection (ESP32 firmware protocol)", "site", "Yes", "No", "—", "Shared by all demos", "own code"),
    ("ASMR Demo/tools/play_thermal_csv.py", "CSV → ESP32 player (no browser)", "1", "Yes", "No", "—", "Works with thermal_mode_A/B.csv", "own code"),
    ("ASMR Demo/tools/render_mp4.py", "Deterministic frame renderer → MP4", "1", "Yes", "Path only", "—", "scripts/render_mp4.py", "own code"),
    ("ASMR Demo 2/output/stems/*.wav", "Demo 2 voice / SFX stems", "2", "No", "—", "—", "Not needed: Demo 3 uses the real song", "VOICEVOX:ずんだもん (credit) / own SFX"),
    ("ASMR Demo 2/output/final_1080p.mp4", "Demo 2 film", "2", "No", "—", "—", "Not reused (different scene)", "own"),
    ("Demo3_ShiningSmileConcert/assets/music_original/*", "Shining Smile Melody – Jpop (ZTMusic, Pixabay)", "3", "Yes", "Edited to 150 s", "—", "Downloaded manually; analysed (scripts/music_features.py), edited at a bar boundary (scripts/edit_music.py); see assets/music_original/SOURCE.md", "Pixabay Content License — verify before public release"),
]


def main():
    rows = ["# Reuse inventory — Demo 3 (Shining Smile Melody — Ice & Fire Concert)", "",
            "Priority: direct reuse > modify > regenerate from existing reference > new. Demo 1 and Demo 2 are read-only (symlinks / imports, never edited).", "",
            "| Path | Type | Demo | Direct reuse | Modify | Missing | Action in Demo 3 | Source / licence |", "|---|---|---|---|---|---|---|---|"]
    for pat, typ, demo, direct, mod, miss, act, lic in RULES:
        files = sorted(glob.glob(os.path.join(SITE, pat)))
        if not files:
            rows.append(f"| `{pat}` | {typ} | {demo} | {direct} | {mod} | **not found** | {act} | {lic} |"); continue
        if len(files) == 1:
            rows.append(f"| `{os.path.relpath(files[0], SITE)}` | {typ} | {demo} | {direct} | {mod} | {miss} | {act} | {lic} |")
        else:
            names = ", ".join(os.path.splitext(os.path.basename(f))[0] for f in files)
            rows.append(f"| `{pat}` ({len(files)} files: {names}) | {typ} | {demo} | {direct} | {mod} | {miss} | {act} | {lic} |")
    rows += ["", "## Licence notes",
             "- **Song**: Pixabay Content License allows free use incl. commercial, editing and public display without attribution; it does not allow selling or redistributing the track as a standalone file. Recorded in `assets/music_original/SOURCE.md` once downloaded. **Check the licence text on the page at download time** before any public release.",
             "- **Character art**: generated by the user with ChatGPT from their own design (Demo 2), reused as-is.",
             "- **Voices**: Demo 3 uses the song's own vocal; no VOICEVOX lines are required unless MCs are added (credit VOICEVOX:ずんだもん if so)."]
    open(os.path.join(ROOT, "reuse_inventory.md"), "w").write("\n".join(rows) + "\n")
    print("reuse_inventory.md:", len(RULES), "entries")


if __name__ == "__main__":
    main()
